import{_ as r,o as e,c as a,a5 as o}from"./chunks/framework.BZzouRtU.js";const s="/study/images/hardware/computer-components.svg",f=JSON.parse('{"title":"コンピュータの部品と役割 — ゲームが動くまで","description":"","frontmatter":{"title":"コンピュータの部品と役割 — ゲームが動くまで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"hardware","summary":"CPU、RAM、SSD、GPU、入出力機器の役割を、ゲームを起動して操作する流れから説明する。OSとドライバー、保存と実行中の状態も結び付ける。","aliases":["コンピュータ","ハードウェア","CPU","RAM","メインメモリ","SSD","ストレージ","GPU","OS","ドライバー","入出力"],"verification":"Microsoftのプロセス・ファイルキャッシュ・Direct3D資料とIntelのCPU資料に照合（2026-11-07）"}},"headers":[],"relativePath":"hardware/computer-components.md","filePath":"hardware/computer-components.md"}'),n={name:"hardware/computer-components.md"};function d(i,t,h,c,l,m){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="コンピュータの部品と役割-—-ゲームが動くまで" tabindex="-1">コンピュータの部品と役割 — ゲームが動くまで <a class="header-anchor" href="#コンピュータの部品と役割-—-ゲームが動くまで" aria-label="Permalink to &quot;コンピュータの部品と役割 — ゲームが動くまで&quot;">​</a></h1><p>ゲームを起動すると、保存されていたプログラムを実行し、キャラクターの状態を更新して画面に画像を表示します。一般的なPCを例に、どの部品が計算し、どの部品がデータを保持し、どの部品が外部とやり取りするかを確認します。</p><h2 id="まず五つの役割を知る" tabindex="-1">まず五つの役割を知る <a class="header-anchor" href="#まず五つの役割を知る" aria-label="Permalink to &quot;まず五つの役割を知る&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名前</th><th>担当すること</th><th>ゲームでの例</th></tr></thead><tbody><tr><td><strong>CPU</strong></td><td>プログラムの命令を実行し、値の計算や条件の判断を進める。</td><td>入力に応じてプレイヤーの位置を更新する。</td></tr><tr><td><strong>RAM・メインメモリ</strong></td><td>実行中に使う命令やデータを置く。通常のRAMは電源を失うと内容を保持できない。</td><td>現在の位置、読み込んだステージ、作業中のデータを置く。</td></tr><tr><td><strong>SSDなどのストレージ</strong></td><td>電源を切った後も残すファイルを保存する。</td><td>ゲーム本体、画像、音、セーブデータを保存する。</td></tr><tr><td><strong>GPU</strong></td><td>多数のデータに対する計算や画像の生成を進める。</td><td>頂点の変換や画面上の色の計算を行う。</td></tr><tr><td><strong>入出力機器</strong></td><td>コンピュータと外側の間で情報を渡す。</td><td>キーボードから入力し、ディスプレイへ表示し、NICで通信する。</td></tr></tbody></table><p>CPUが実行する命令列を<strong>プログラム</strong>と呼びます。画像や位置など、命令が読み書きする値が<strong>データ</strong>です。プログラム自体も、保存や転送をするときにはバイトの列として扱えます。<a href="/study/hardware/cpu/instruction-execution.html">CPUの命令実行</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoftのプロセスの構成</a></p><figure class="study-figure"><img src="'+s+'" alt="ゲームの実行では、OSとドライバーが部品の利用を支える。SSDに保存された必要部分をRAMへ読み、CPUが命令を実行する。描画データとコマンドを使ってGPUが画像を生成し、ディスプレイへ表示する。" width="760" height="470" loading="lazy"><figcaption>ゲーム起動と表示に関わる部品の概念図です。矢印は主な役割のつながりを示します。<a href="/study/images/hardware/computer-components.svg" target="_blank" rel="noopener noreferrer">部品と役割の図を拡大</a></figcaption></figure><h2 id="起動すると、保存したファイルから実行中の状態が生まれる" tabindex="-1">起動すると、保存したファイルから実行中の状態が生まれる <a class="header-anchor" href="#起動すると、保存したファイルから実行中の状態が生まれる" aria-label="Permalink to &quot;起動すると、保存したファイルから実行中の状態が生まれる&quot;">​</a></h2><ol><li><strong>ゲームの起動を要求する。</strong> Windowsなどの<strong>OS（基本ソフトウェア）<strong>が、プログラムを動かすための</strong>プロセス</strong>を作ります。プロセスは、使用するメモリ空間や開いたファイルなどの資源をまとめた実行の単位です。</li><li><strong>必要な命令とデータを使える状態にする。</strong> OSは実行ファイルや関連ファイルを扱い、ゲームが必要なメモリを利用できるようにします。起動時に全ファイルを一度に読む方式もあれば、必要になった部分を後で読む方式もあります。</li><li><strong>CPUが処理を進める。</strong> OSが実行の順番を割り当てる<strong>スレッド</strong>に沿って、CPUが命令を実行します。ゲームは入力を調べ、位置などのデータを更新します。</li><li><strong>GPUで画像を作る。</strong> ゲームが描画に必要なデータとコマンドを用意し、グラフィックスAPIを通じてGPUに仕事を渡します。生成した画像は表示に使われます。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoftのプロセスとスレッド</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/atoc-dx-graphics-direct3d-11" target="_blank" rel="noreferrer">MicrosoftのDirect3D 11の描画機能</a> · <a href="/study/os/process-startup.html">起動の詳細</a></li></ol><p>RAMに読み込んだデータをCPUが使うときは、CPUの近くにある<strong>キャッシュ</strong>も働きます。また、同じファイルを再び読む際、OSがRAMに残していた内容を利用できることがあります。ゲームの「ロード」は、ストレージからの読み取りに加え、圧縮データの展開や、GPUで使える形への準備も含みます。<a href="/study/hardware/memory/ram-cache-and-storage.html">RAM・キャッシュ・ストレージ</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-caching" target="_blank" rel="noreferrer">Microsoftのファイルキャッシュ</a> · <a href="/study/game/asset-loading.html">アセットの読み込み</a></p><h2 id="osとドライバーは何をするか" tabindex="-1">OSとドライバーは何をするか <a class="header-anchor" href="#osとドライバーは何をするか" aria-label="Permalink to &quot;OSとドライバーは何をするか&quot;">​</a></h2><p>OSは、複数のアプリがCPU、メモリ、ファイルなどを使うための仕組みを提供します。例えば、ゲームとブラウザーを同時に開いているとき、OSはそれぞれのスレッドを実行させ、各プロセスのメモリを管理します。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoftのプロセスとスレッド</a></p><p><strong>ドライバー</strong>は、OSと機器の間で、機器に応じた操作や結果の受け渡しを担当するソフトウェアです。ゲームがファイルを読むときや描画を依頼するときには、OSやドライバーの仕組みを通じて実際の機器を利用します。例えばNICのドライバーは、受信したデータをOS側へ渡せるように処理します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/what-is-a-driver-" target="_blank" rel="noreferrer">Microsoftのドライバーの説明</a> · <a href="/study/hardware/io/nic-receive-queues.html">NICの受信経路</a></p><h2 id="保存と、実行中に変わる値" tabindex="-1">保存と、実行中に変わる値 <a class="header-anchor" href="#保存と、実行中に変わる値" aria-label="Permalink to &quot;保存と、実行中に変わる値&quot;">​</a></h2><p>ゲームの中でキャラクターを移動すると、実行中の位置の値が変わります。その状態を次の起動でも使いたいなら、ゲームは必要な情報を<strong>セーブファイル</strong>などへ書き出します。実行中のデータを変更しただけで、すべての変更が自動的にセーブされるわけではありません。<a href="/study/os/file-read-journey.html">ファイルを読むと内部で何が起きるか</a></p><table tabindex="0"><thead><tr><th>操作</th><th>変わるもの</th></tr></thead><tbody><tr><td>ゲームをインストールする</td><td>ストレージ上にゲームのファイルが置かれる。</td></tr><tr><td>ゲームを起動する</td><td>プロセスが作られ、実行中の状態が用意される。</td></tr><tr><td>キャラクターを移動する</td><td>実行中の位置などが更新される。</td></tr><tr><td>セーブする</td><td>次回使いたい状態が保存先へ書き出される。</td></tr></tbody></table><h2 id="同じ役割でも、物理的な形は変わる" tabindex="-1">同じ役割でも、物理的な形は変わる <a class="header-anchor" href="#同じ役割でも、物理的な形は変わる" aria-label="Permalink to &quot;同じ役割でも、物理的な形は変わる&quot;">​</a></h2><p>CPU、GPU、メモリなどは、必ず一つずつ独立した基板に載っているわけではありません。CPUとGPUを同じパッケージに備える構成や、GPUがメインメモリを共有する構成もあります。部品の役割を追い、その後に実際の接続や共有の仕方を調べると、PCとゲーム機、スマートフォンの構成も比較できます。<a href="/study/hardware/gpu/what-is-gpu.html">GPUとは何か</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/memory-management-strategies" target="_blank" rel="noreferrer">MicrosoftのUMAと専用メモリを持つ構成</a></p><p>CPUが個々の命令をどう進めるかは<a href="/study/hardware/cpu/instruction-execution.html">CPUの命令実行</a>、RAMとSSDを使い分ける理由は<a href="/study/hardware/memory/ram-cache-and-storage.html">RAM・キャッシュ・ストレージ</a>で詳しく扱います。</p>',18)])])}const u=r(n,[["render",d]]);export{f as __pageData,u as default};
